.scrap { position: relative; padding: 7px 16px 7px 9px; background: #fffdf6; box-shadow: 1px 2px 0 rgba(60,50,30,.10), 3px 5px 10px rgba(60,50,30,.12); transform: rotate(-1.4deg); }
.scrap::before { content: ''; position: absolute; left: 44%; top: -10px; width: 58px; height: 18px; transform: rotate(-5deg); background: linear-gradient(180deg, rgba(255,255,255,.28), rgba(255,255,255,0) 40%), rgba(238,226,186,.85); box-shadow: 0 1px 2px rgba(80,60,30,.18); clip-path: polygon(0 8%, 6% 0, 12% 10%, 88% 0, 94% 8%, 100% 0, 100% 92%, 94% 100%, 88% 90%, 12% 100%, 6% 92%, 0 100%); }
.bar { position: relative; width: 232px; height: 22px; overflow: hidden; background: #fff; border: 2.5px solid #2b2a30; border-radius: 12px 5px 10px 4px / 5px 10px 4px 12px; }
.bar-fill { height: 100%; background: repeating-linear-gradient(-58deg, rgba(226,54,44,.95) 0 3.5px, rgba(226,54,44,.6) 3.5px 6px); clip-path: polygon(0 0, calc(100% - 6px) 0, 100% 25%, calc(100% - 5px) 50%, 100% 75%, calc(100% - 6px) 100%, 0 100%); }
.ruler { position: relative; height: 26px; overflow: hidden; border: 2px solid #8a6326; border-radius: 3px; background: repeating-linear-gradient(90deg, rgba(110,70,25,.8) 0 1.5px, transparent 1.5px 12px) 6px 0 / 100% 7px no-repeat, repeating-linear-gradient(90deg, rgba(110,70,25,.8) 0 2px, transparent 2px 60px) 6px 0 / 100% 12px no-repeat, linear-gradient(180deg, #fbe08a, #f1c75a); }
.ruler-fill { position: absolute; left: 0; top: 12px; bottom: 3px; background: repeating-linear-gradient(-62deg, rgba(66,168,234,.95) 0 3px, rgba(66,168,234,.55) 3px 5px); }
.sticky { padding: 8px 26px 6px; background: linear-gradient(180deg, #fff6a8, #ffec7e); transform: rotate(1.6deg); border-radius: 2px 3px 14px 2px; box-shadow: 2px 4px 0 rgba(60,50,30,.12); font: 400 40px/1 'Gochi Hand', cursive; color: #2a5ec8; }
.card { position: relative; width: 232px; min-height: 304px; padding: 42px 18px 22px; background: #fffdf6; border: 3px solid #e2362c; border-radius: 18px 6px 22px 5px / 6px 20px 6px 18px; transform: rotate(-2deg); box-shadow: 0 0 0 1.5px rgba(226,54,44,.35), 3px 6px 0 rgba(60,50,30,.12); }
.card-key { width: 34px; height: 34px; display: flex; align-items: center; justify-content: center; font: 400 21px 'Gochi Hand', cursive; color: #e2362c; border: 2.5px solid currentColor; border-radius: 52% 46% 55% 44% / 48% 55% 45% 52%; }
